    dwAlarmWord := dwAlarmWord OR 16#00000200; (* Die Thermal Runaway / API Degradation Risk *)
ELSIF (rFilter_DieTemp - rDieTemp_Setpoint) < rDieTemp_Tol_Low THEN
    dwAlarmWord := dwAlarmWord OR 16#00000400; (* Die Cold Plug / Crystallization Risk *)
ELSE
    dwAlarmWord := dwAlarmWord AND NOT 16#00000600;
END_IF;

(* Strand Breakage / Haul-Off Tension Loss *)
IF (iState = 60) AND (rFilter_Tension < 2.0) THEN
    dwAlarmWord := dwAlarmWord OR 16#00000800; (* Strand Broken Warning *)
ELSE
    dwAlarmWord := dwAlarmWord AND NOT 16#00000800;
END_IF;

(* === 10. PACKED STATUS BITFIELD ENCODING === *)
wExtruderStatusWord.0 := bSystemReady;
wExtruderStatusWord.1 := bProcessInSpec;
wExtruderStatusWord.2 := (iState = 60);         (* Production active *)
wExtruderStatusWord.3 := (iHealthySensorCount = 3); (* 2oo3 Full Health *)
wExtruderStatusWord.4 := (iHealthySensorCount = 2); (* 2oo3 Degraded *)
wExtruderStatusWord.5 := (rScrewSpeed_Actual > 5.0);(* Extruder rotating *)
wExtruderStatusWord.6 := (rTotalMassFlow_kgh > 0.1);(* Feeders dosing *)
wExtruderStatusWord.7 := (dwAlarmWord <> 0);    (* Group alarm active *)

END_FUNCTION_BLOCK
