    rSteeringPadForce_kN            : REAL;     (* Commanded dynamic hydraulic steering pad lateral push force [kN] (0.0..45.0) *)
    rPadActuationPhase_Deg          : REAL;     (* Synchronized collar rotation pad firing phase angle offset [deg] (0.0..360.0) *)
