   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_INIT_TELEMETRY_SYNC: Downhole Power-Up & Mud Carrier Lock *)
        bSystemReady                     := FALSE;
        bSteeringEngaged                 := FALSE;
        bDegradedModeActive              := FALSE;
        rSteeringPadForce_kN             := 0.0;
