    (* Discrete-time system state transition matrix coefficients (Ts = 2ms) *)
    cA11                        : REAL := 0.9850;
    cA12                        : REAL := -12.4500;
    cA13                        : REAL := 18.2000;
    cA21                        : REAL := 0.00012;
    cA22                        : REAL := 0.8920;
    cA23                        : REAL := -0.0045;
    cA31                        : REAL := 0.00008;
    cA32                        : REAL := 0.0520;
    cA33                        : REAL := 0.9410;

